object Solution {
  def numberOfArithmeticSlices(nums: Array[Int]): Int = {
    val n = nums.length
    // Each element i has a map from difference -> count of arithmetic subsequences ending at i with that difference
    val dp = Array.fill(n)(scala.collection.mutable.Map.empty[Long, Int])
    var result = 0

    for (i <- nums.indices) {
      for (j <- 0 until i) {
        val diff = nums(i).toLong - nums(j).toLong
        val countAtJ = dp(j).getOrElse(diff, 0)
        // Subsequences ending at j with diff can be extended by nums(i)
        // Also, the pair (nums(j), nums(i)) forms a new subsequence of length 2
        val countAtI = dp(i).getOrElse(diff, 0)
        dp(i).update(diff, countAtI + countAtJ + 1)
        // Only subsequences extended from j (countAtJ) contribute to result because they have length >= 2,
        // and adding nums(i) makes length >= 3
        result += countAtJ
      }
    }
    result
  }
}

